console.assert(taskGraph.has('task1') === true, 'task1 should exist');
console.assert(taskGraph.has('task4') === false, 'task4 should not exist');

// Test size method
console.assert(taskGraph.size() === 3, 'Size should be 3');

// Test error for duplicate ID
try {
