        return false;
    } catch (error) {
        if (error.message.includes('Invalid money format')) {
            console.log("Error handling test 2 passed: Empty string correctly throws error");
        } else {
            console.error("Error test 2 failed: Wrong error message:", error.message);
            return false;
        }
    }
    
    try {
