    expected = {}
    assert result == expected, f"Expected {expected}, got {result}"
    
    # Test empty string
    result = r2_text.bigrams("")
    expected = {}
    assert result == expected, f"Expected {expected}, got {result}"
    
    print("All bigrams tests passed!")

if __name__ == "__main__":
