        console.assert(JSON.stringify(result2) === JSON.stringify(expected2), 
            `Test 2 failed: splitMoney(1000, 4) should equal [250, 250, 250, 250], got ${JSON.stringify(result2)}`);
        
        // Test case with remainder 1
