        console.log("task2:", task2);
      }
      
      if (task3 && task3.duration === 15 && task3.deps.length === 1 && task3.deps[0] === 'task1') {
        console.log("PASS: task3 data correct");
      } else {
        console.log("FAIL: task3 data incorrect");
        console.log("task3:", task3);
      }
    } else {
