  return names.map(name => {
    const balance = ledger.balance(name);
    const balanceCents = Math.round(balance * 100);
    const interestCents = multiplyMoney(balanceCents, ratePct / 100);
    return `${name}: ${formatMoney(interestCents)}`;
  });
}

// Function to even split balance from one account to multiple accounts
function evenSplit(ledger, from, names) {
  const balance = ledger.balance(from);
  const balanceCents = Math.round(balance * 100);
  
  // Split the balance as evenly as possible
  const splits = splitMoney(balanceCents, names.length);
  
  // Transfer each split amount to the corresponding account
  splits.forEach((amount, index) => {
    if (amount > 0) {
      ledger.transfer(from, names[index], amount / 100);
    }
  });
  
  return splits;
}

// Function to get the n accounts with the highest balances
function richest(ledger, n) {
  // Get CSV data from ledger
  const csvData = ledger.toCSV();
  
  // Parse CSV data to extract account names and balances
  const lines = csvData.split('\n');
  const accounts = [];
  
  // Skip the header line
  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (line) {
      const parts = line.split(',');
      if (parts.length >= 2) {
        const name = parts[0].trim();
        const balance = parseFloat(parts[1].trim());
        accounts.push({ name, balance });
      }
    }
  }
  
  // Sort accounts by balance (descending), then by name (ascending) for ties
  accounts.sort((a, b) => {
    if (b.balance !== a.balance) {
      return b.balance - a.balance; // Higher balance first
    }
    return a.name.localeCompare(b.name); // Alphabetical order for ties
  });
  
  // Return the top n account names
  return accounts.slice(0, n).map(account => account.name);
}

