        console.assert(multiplyMoney(100, 1.75) === 175, 'Test 8 failed: 100 * 1.75 should equal 175');
        
        console.log("All multiplyMoney tests passed!");
        return true;
    } catch (error) {
        console.error("multiplyMoney test failed:", error.message);
