    const tax = taxMoney(balanceCents, ratePct);
    const net = addMoney(balance, -tax);
    const gross = balance;
    
    return `${name}: net ${formatMoney(net)} tax ${formatMoney(tax)} gross ${formatMoney(gross)}`;
  });
}

