try {
  const originalGraph = new TaskGraph();
  originalGraph.add('A', 5)
              .add('B', 3)
              .add('C', 4)
              .depend('B', 'A')
              .depend('C', 'A');
  
  const json2 = originalGraph.toJSON();
  const restoredGraph = TaskGraph.fromJSON(json2);
  
  // Check if the restored graph has the same tasks and dependencies
